1	// The structural comparison behind src/oracle.ts: both sides' prop types reduced to one shape, and one verdict per
2	// pair. Pure: nothing here talks to the checker.
3	
4	/** A type reduced to what both sides can state: kind, literal value, members, fields, parameters. `alias` is the
5	 * checker's name for it (an alias, or the interface that declares it), which Caliper may print instead. */
6	export type Norm = (
7	  | { k: 'prim'; name: string }
8	  | { k: 'lit'; value: string }
9	  | { k: 'union'; members: Norm[] }
10	  | { k: 'intersection'; members: Norm[] }
11	  | { k: 'array'; element: Norm }
12	  | { k: 'tuple'; elements: Norm[] }
13	  | { k: 'function'; params: { optional: boolean; rest: boolean; type: Norm }[]; returns: Norm }
14	  | { k: 'object'; fields: string[]; index: boolean; indexValue?: Norm }
15	  | { k: 'name'; name: string }
16	  | { k: 'param'; name: string; fallback?: Norm; constraint?: Norm }
17	  | { k: 'opaque' }
18	  | { k: 'error' }
19	) & { alias?: string }
20	
21	export type Verdict = 'identical' | 'spelled' | 'less precise' | 'wrong' | 'checker any/error'
22	
23	export const MAX_DEPTH = 3
24	export const VERDICTS: Verdict[] = ['identical', 'spelled', 'less precise', 'wrong', 'checker any/error']
25	const RANK: Verdict[] = ['identical', 'spelled', 'less precise', 'wrong']
26	
27	/** A type name without `React.` or a namespace qualifier. */
28	export const bareName = (name: string) => name.replace(/^.*\./, '')
29	export const prim = (name: string): Norm => ({ k: 'prim', name })
30	
31	const TERMINALS: Record<string, string> = {
32	  reactNode: 'ReactNode',
33	  cssProperties: 'CSSProperties',
34	  elementType: 'ElementType',
35	  htmlAttributes: 'HTMLAttributes',
36	  ref: 'Ref',
37	  sxProps: 'SxProps',
38	}
39	const PRIMITIVES = new Set(['string', 'number', 'boolean', 'null', 'undefined', 'any', 'unknown', 'never', 'void'])
40	const LITERALS = new Set(['stringLiteral', 'numberLiteral', 'boolLiteral'])
41	
42	const isIndexField = (field: any) => field.indexKey !== undefined
43	
44	/** Caliper's canonical `PropType` JSON, normalized. */
45	export function caliperNorm(t: any, depth = 0): Norm {
46	  if (!t || depth > MAX_DEPTH) return { k: 'opaque' }
47	  if (PRIMITIVES.has(t.kind)) return prim(t.kind)
48	  if (LITERALS.has(t.kind)) return { k: 'lit', value: String(t.value) }
49	  const inner = (m: any) => caliperNorm(m, depth + 1)
50	  switch (t.kind) {
51	    case 'literalUnion': {
52	      return { k: 'union', members: t.members.map((m: string) => ({ k: 'lit', value: m })) }
53	    }
54	    case 'union': {
55	      return { k: 'union', members: t.members.map((m: any) => inner(m)) }
56	    }
57	    case 'intersection': {
58	      const parts: Norm[] = t.members.map((m: any) => inner(m))
59	      const meaningful = parts.filter((m) => !(m.k === 'object' && m.fields.length === 0))
60	      return meaningful.length === 1 ? meaningful[0] : { k: 'intersection', members: parts }
61	    }
62	    case 'array': {
63	      return { k: 'array', element: inner(t.element) }
64	    }
65	    case 'tuple': {
66	      return { k: 'tuple', elements: (t.elements ?? t.members ?? []).map((m: any) => inner(m)) }
67	    }
68	    case 'object': {
69	      // Caliper writes an index signature as one field whose `indexKey` is the key type: its name is the signature's
70	      // parameter name (`[id: string]: number`), not a property.
71	      const indexed: any[] = t.fields.filter(isIndexField)
72	      const named: any[] = t.fields.filter((field: any) => !isIndexField(field))
73	      const indexValues: Norm[] = indexed.map((field) => inner(field.propType))
74	      return {
75	        k: 'object',
76	        fields: named.map((field) => field.name).toSorted(),
77	        index: indexed.length > 0,
78	        ...(indexed.length > 0 && {
79	          indexValue: indexValues.length === 1 ? indexValues[0] : { k: 'union', members: indexValues },
80	        }),
81	      }
82	    }
83	    // A `readonly` array or tuple is the array or tuple, as the checker reads it.
84	    case 'readonly': {
85	      return caliperNorm(t.element, depth)
86	    }
87	    case 'function': {
88	      const params = (t.params ?? []).map((p: any) => ({
89	        optional: p.optional === true,
90	        rest: p.rest === true,
91	        type: inner(p.type),
92	      }))
93	      return { k: 'function', params, returns: inner(t.returnType) }
94	    }
95	    case 'named': {
96	      return { k: 'name', name: bareName(t.name) }
97	    }
98	    default: {
99	      return TERMINALS[t.kind] ? { k: 'name', name: TERMINALS[t.kind] } : { k: 'opaque' }
100	    }
101	  }
102	}
103	
104	const worst = (vs: Verdict[]): Verdict => vs.reduce((a, b) => (RANK.indexOf(b) > RANK.indexOf(a) ? b : a), 'identical')
105	const best = (vs: Verdict[]): Verdict => vs.reduce((a, b) => (RANK.indexOf(b) < RANK.indexOf(a) ? b : a), 'wrong')
106	const isLit = (n: Norm, value?: string) => n.k === 'lit' && (value === undefined || n.value === value)
107	const isUndefined = (m: Norm) => m.k === 'prim' && m.name === 'undefined'
108	const WIDENING = new Set(['string', 'number', 'boolean'])
109	
110	/** An empty object type, or `Record<…>` (its arguments are not kept): what `string & {}` intersects with. */
111	const isEmptyObject = (m: Norm) =>
112	  (m.k === 'object' && m.fields.length === 0 && !m.index) || (m.k === 'name' && m.name === 'Record')
113	
114	/** Whether `m` is the primitive `name`, or `name & {}`, or a union with either. */
115	function absorbs(m: Norm, name: string): boolean {
116	  if (m.k === 'prim') return m.name === name
117	  if (m.k === 'union') return m.members.some((member) => absorbs(member, name))
118	  return m.k === 'intersection' && m.members.some(isEmptyObject) && m.members.some((member) => absorbs(member, name))
119	}
120	
121	/** A name or opaque type that Caliper (or the checker) did not expand: what it holds is unknown, so no member beside it
122	 * can prove the other side wrong. */
123	const isUnexpanded = (m: Norm) => m.k === 'name' || m.k === 'opaque'
124	
125	/** Union members without `undefined` (an optional prop's, which both sides treat as optional), flattened, with
126	 * `true | false` as `boolean`. */
127	function members(n: Norm, coverLiterals = false): Norm[] {
128	  const flat: Norm[] = []
129	  const push = (m: Norm) => {
130	    if (m.k === 'union') m.members.forEach(push)
131	    // An optional generic prop reads `T | (undefined & T)`.
132	    else if (!isUndefined(m) && !(m.k === 'intersection' && m.members.some(isUndefined))) flat.push(m)
133	  }
134	  push(n)
135	  // `'default' | 'large' | string` is `string` to the checker: a literal that a primitive of its kind in the same
136	  // union already covers adds nothing, so a union written with it holds the same values as one without. The checker's
137	  // `"blue" | … | (string & {})` keeps its literals for the reader, so `compare` scores it spelled, not identical. A
138	  // `true`/`false` literal is boolean's, not string's.
139	  // `string & {}` and `string & Record<never, never>` (the `LiteralUnion` spellings) are `string` for this purpose.
140	  const has = (name: string) => flat.some((m) => absorbs(m, name))
141	  const covered = (m: Norm) =>
142	    coverLiterals &&
143	    m.k === 'lit' &&
144	    m.value !== 'true' &&
145	    m.value !== 'false' &&
146	    (/^-?\d+(\.\d+)?$/.test(m.value) ? has('number') : has('string'))
147	  const kept = flat.filter((m) => !covered(m))
148	  if (kept.some((m) => isLit(m, 'true')) && kept.some((m) => isLit(m, 'false'))) {
149	    return [...kept.filter((m) => !isLit(m, 'true') && !isLit(m, 'false')), prim('boolean')]
150	  }
151	  return kept
152	}
153	
154	/** Two unions: each checker member covered by one of Caliper's (a missing member makes Caliper's type too narrow),
155	 * and each of Caliper's matched by one of the checker's (an extra member makes it too wide, unless it widens
156	 * literals). */
157	function compareUnions(cm: Norm[], km: Norm[], depth: number): Verdict {
158	  const kCovered = km.map((m) => best(cm.map((cMember) => compare(cMember, m, depth + 1))))
159	  const cMatched = cm.map((m) => {
160	    const verdict = best(km.map((kMember) => compare(m, kMember, depth + 1)))
161	    const widens =
162	      m.k === 'prim' &&
163	      WIDENING.has(m.name) &&
164	      km.some((kMember) => kMember.k === 'lit' || (kMember.k === 'prim' && kMember.name === m.name))
165	    return verdict === 'wrong' && widens ? 'less precise' : verdict
166	  })
167	  const verdict = worst([...kCovered, ...cMatched])
168	  // A union with a name or opaque member (`MantineColor | 'initials'`, a template literal) may hold the other side's
169	  // values in that member, so a member it cannot match is not proof of a different type.
170	  return verdict === 'wrong' && [...cm, ...km].some((m) => isUnexpanded(m)) ? 'less precise' : verdict
171	}
172	
173	function compareFunctions(c: Norm & { k: 'function' }, k: Norm & { k: 'function' }, depth: number): Verdict {
174	  const verdicts: Verdict[] = [compare(c.returns, k.returns, depth + 1)]
175	  for (const [i, kp] of k.params.entries()) {
176	    const cp = c.params[i]
177	    if (cp === undefined) {
178	      verdicts.push(kp.optional || kp.rest ? 'less precise' : 'wrong')
179	    } else {
180	      verdicts.push(compare(cp.type, kp.type, depth + 1))
181	      // A marker the checker has and this side lost.
182	      if ((kp.optional && !cp.optional) || (kp.rest && !cp.rest)) verdicts.push('less precise')
183	    }
184	  }
185	  if (c.params.length > k.params.length) verdicts.push('wrong')
186	  return worst(verdicts)
187	}
188	
189	/** One non-union type against another. */
190	function compareOne(c: Norm, k: Norm, depth: number): Verdict {
191	  switch (k.k) {
192	    case 'prim': {
193	      return c.k === 'prim' && c.name === k.name ? 'identical' : 'wrong'
194	    }
195	    case 'lit': {
196	      if (c.k === 'lit') return c.value === k.value ? 'identical' : 'wrong'
197	      return c.k === 'prim' && WIDENING.has(c.name) ? 'less precise' : 'wrong'
198	    }
199	    case 'array': {
200	      return c.k === 'array' ? compare(c.element, k.element, depth + 1) : 'wrong'
201	    }
202	    case 'tuple': {
203	      if (c.k !== 'tuple') return c.k === 'array' ? 'less precise' : 'wrong'
204	      if (c.elements.length !== k.elements.length) return 'wrong'
205	      return worst(c.elements.map((e, i) => compare(e, k.elements[i], depth + 1)))
206	    }
207	    case 'function': {
208	      return c.k === 'function' ? compareFunctions(c, k, depth) : 'wrong'
209	    }
210	    case 'object': {
211	      if (c.k !== 'object') return c.k === 'prim' && c.name === 'object' ? 'less precise' : 'wrong'
212	      const own = new Set(c.fields)
213	      if (c.fields.some((f) => !k.fields.includes(f))) return 'wrong'
214	      // An index signature Caliper has and the checker does not describes a different type.
215	      if (c.index && !k.index) return 'wrong'
216	      const verdicts: Verdict[] = [
217	        k.fields.some((f) => !own.has(f)) || (k.index && !c.index) ? 'less precise' : 'identical',
218	      ]
219	      if (c.indexValue && k.indexValue) verdicts.push(compare(c.indexValue, k.indexValue, depth + 1))
220	      return worst(verdicts)
221	    }
222	    case 'intersection': {
223	      if (c.k !== 'intersection') return 'less precise'
224	      return c.members.length === k.members.length ? 'identical' : 'less precise'
225	    }
226	    case 'param': {
227	      // A type parameter of the component itself, which Caliper replaced with an instantiation: its default, as a bare
228	      // `AccordionProps` means `AccordionProps<false>`, or its constraint. That is one instance of the parameter,
229	      // looser or narrower than the parameter itself, and not another type; a type that is neither instance is.
230	      // `c` may be one member of a union Caliper wrote out (`string` of `string | number`), so it must fit one member of
231	      // an instance, not all of them.
232	      const instances = [k.fallback, k.constraint].filter((i): i is Norm => i !== undefined).flatMap((i) => members(i))
233	      // A parameter with neither (a generic component cast over `forwardRef`, whose props interface declares the
234	      // default) leaves the checker no instance to hold Caliper's to: any one it picked is one value of the parameter.
235	      if (instances.length === 0) return 'less precise'
236	      return instances.some((i) => compare(c, i, depth + 1) !== 'wrong') ? 'less precise' : 'wrong'
237	    }
238	    default: {
239	      return 'wrong'
240	    }
241	  }
242	}
243	
244	/** How Caliper's normalized type `c` stands against the checker's `k`. A checker union that spells literals a
245	 * primitive in it already covers (`'a' | 'b' | (string & {})`) holds the values Caliper's `string` does, spelled
246	 * another way. */
247	export function compare(c: Norm, k: Norm, depth = 0): Verdict {
248	  const verdict = compareValues(c, k, depth)
249	  return verdict === 'identical' && members(k).length !== members(k, true).length ? 'spelled' : verdict
250	}
251	
252	function compareValues(c: Norm, k: Norm, depth: number): Verdict {
253	  if (depth > MAX_DEPTH) return 'identical'
254	  // The checker has no type to compare with: an error, `any`, or a top-level `unknown` where Caliper has a type
255	  // (most often a declaration the program couldn't resolve).
256	  const uninformative =
257	    k.k === 'error' || (k.k === 'prim' && k.name === 'any') || (depth === 0 && k.k === 'prim' && k.name === 'unknown')
258	  if (uninformative && !(c.k === 'prim' && k.k === 'prim' && c.name === k.name)) {
259	    return depth === 0 ? 'checker any/error' : 'identical'
260	  }
261	  const km = members(k, true)
262	  // An optional prop of type `never` reads `undefined` in the checker, which `members` drops as the optional marker.
263	  if (km.length === 0 && c.k === 'prim' && c.name === 'never') return 'identical'
264	  if (c.k === 'name') {
265	    // An optional prop's checker type is `X | undefined`; the name is X's.
266	    const target = km.length === 1 ? km[0] : k
267	    if ((target.alias && bareName(target.alias) === c.name) || (k.alias && bareName(k.alias) === c.name)) {
268	      return 'spelled'
269	    }
270	    if (target.k === 'param' && target.name === c.name) return 'identical'
271	    // A name Caliper left unexpanded where the checker has the type itself (an unbound parameter, an alias that
272	    // resolves to another name).
273	    return 'less precise'
274	  }
275	  if (k.k === 'opaque') return 'identical'
276	  if (c.k === 'opaque') return 'less precise'
277	  if (c.k === 'prim' && (c.name === 'any' || c.name === 'unknown') && !(k.k === 'prim' && k.name === c.name)) {
278	    return 'less precise'
279	  }
280	  // An intersection Caliper left as written, which the checker reduced (`Mode & …` to a literal union).
281	  if (c.k === 'intersection' && !km.some((m) => m.k === 'intersection')) return 'less precise'
282	  const cm = members(c, true)
283	  if (cm.length !== 1 || km.length !== 1) return compareUnions(cm, km, depth)
284	  const [cOne] = cm
285	  const [kOne] = km
286	  if (cOne !== c || kOne !== k) return compare(cOne, { ...kOne, alias: kOne.alias ?? k.alias }, depth)
287	  return compareOne(c, k, depth)
288	}
