130	    if (m.k === 'union') m.members.forEach(push)
131	    // An optional generic prop reads `T | (undefined & T)`.
132	    else if (!isUndefined(m) && !(m.k === 'intersection' && m.members.some(isUndefined))) flat.push(m)
