147	export interface RdtType {
148	  name: string
149	  raw?: string
150	  value?: { value: string }[]
151	}
152	
153	/** An RDT prop type. A literal union is the union of its values; the `raw` name (`SizeType`) is the alias RDT expanded. */
154	export function rdtNorm(type: RdtType | undefined): Norm {
155	  if (!type) return OPAQUE
156	  if (type.name === 'enum') {
157	    if (!type.value?.length) return OPAQUE
158	    const alias = type.raw && /^[A-Za-z_$][\w$]*$/.test(type.raw) ? type.raw : undefined
159	    return { k: 'union', members: type.value.map((v) => typeFromText(v.value)), alias }
160	  }
161	  return typeFromText(type.name)
162	}
163	
164	/** What react-docgen reports for a prop's type (`prop.tsType`), without `signature`. */
165	export interface RdgType {
166	  name: string
167	  raw?: string
168	  value?: string
169	  elements?: RdgType[]
170	}
171	
172	// A `name` that is a kind of type react-docgen reports with a source text, not a type of that name.
173	const KINDS = new Set(['union', 'intersection', 'signature', 'tuple', 'Array', 'literal'])
174	
175	/** A react-docgen prop type: the source text it kept where it kept one (`raw`), else what its `name` and `elements` say. */
176	export function rdgNorm(type: RdgType | undefined): Norm {
177	  if (!type) return OPAQUE
178	  if (type.name === 'literal') return type.value === undefined ? OPAQUE : typeFromText(type.value)
179	  if (type.raw) return typeFromText(type.raw)
180	  const members = (type.elements ?? []).map((e) => rdgNorm(e))
181	  if (type.name === 'union' && members.length > 0) return { k: 'union', members }
182	  if (type.name === 'intersection' && members.length > 0) return { k: 'intersection', members }
183	  if (type.name === 'Array' && members.length === 1) return { k: 'array', element: members[0] }
184	  if (type.name === 'tuple' && members.length > 0) return { k: 'tuple', elements: members }
185	  return KINDS.has(type.name) ? OPAQUE : typeFromText(type.name)
186	}
