    expect(typeFromText('-1')).toStrictEqual(lit('-1', 'number'))
    expect(typeFromText('true')).toStrictEqual(lit('true', 'boolean'))
    expect(typeFromText('"true"')).toStrictEqual(lit('true', 'string'))
  })
