  if (n && typeof n === 'object') {
    const out: any = Object.fromEntries(Object.entries(n).map(([k, v]) => [k, withKind(v)]))
    if (out.k === 'lit' && out.of === undefined) {
      out.of = out.value === 'true' || out.value === 'false' ? 'boolean' : /^-?\d+(\.\d+)?$/.test(out.value) ? 'number' : 'string'
    }
    return out
  }
  return n
}

let pairs = 0
let changed = 0
const seen = new Set<string>()
for (const run of ['A', 'B']) {
  for (const corpus of ['antd', 'chakra', 'mantine', 'shadcn', 'spectrum']) {
    const d = JSON.parse(readFileSync(`/tmp/claude-501/oracle-rerun/${run}/work/${corpus}.oracle.json`, 'utf8'))
    const rows: { where: string; c: any; k: any }[] = []
    for (const [verdict, list] of Object.entries<any[]>(d.examples)) {
