      }
    }
    for (const [tool, v] of Object.entries<any>(d.tools)) {
      for (const [verdict, list] of Object.entries<any[]>(v.examples ?? {})) {
        for (const e of list) rows.push({ where: `${run}/${corpus}/${tool}/${verdict}/${e.component}.${e.prop}`, c: e.tool, k: e.checker })
      }
    }
    for (const { where, c, k } of rows) {
      if (!c || !k) continue
      pairs++
      const before = oldCompare(c, k)
      const after = newCompare(withKind(c), withKind(k))
      if (before !== after) {
        changed++
        const key = `${before}->${after}:${JSON.stringify(c)}|${JSON.stringify(k)}`
        if (!seen.has(key)) {
          seen.add(key)
          console.log(where, before, '->', after)
        }
      }
    }
  }
}
